package app.kivo.store;
import java.util.*;
public class InstalledPackagesTest {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static final class Fake implements InstalledPackages.Backend<String>{boolean failAll,failLauncher;List<String> all=Arrays.asList("org.external.app","org.installed.app","bad",null);Set<String> present=new HashSet<>(Arrays.asList("org.external.app","org.installed.app","org.launcher.app","org.tracked.app"));Map<String,Integer> lookups=new HashMap<>();public List<String> all()throws Exception{if(failAll)throw new Exception("enumeration unavailable");return all;}public List<String> launchers()throws Exception{if(failLauncher)throw new Exception("launcher unavailable");return Arrays.asList("org.launcher.app","org.installed.app","org.launcher.app");}public String lookup(String pkg)throws Exception{lookups.put(pkg,lookups.getOrDefault(pkg,0)+1);if(!present.contains(pkg))throw new Exception("not installed");return pkg;}public String id(String value){if("bad".equals(value))throw new IllegalArgumentException();return value;}}
 public static void main(String[] args){
 Fake source=new Fake();InstalledPackages.Result<String> result=new InstalledPackages<>(source).collect(Arrays.asList("org.tracked.app","org.only.downloaded"));check(result.packages.size()==4,"All, launcher and tracked actual installs are merged");check(result.packages.containsKey("org.external.app"),"Externally installed apps need no Kivo history");check(!result.packages.containsKey("org.only.downloaded"),"An APK record is never proof of installation");check(source.lookups.get("org.launcher.app")==1,"Launcher duplicates must not trigger duplicate lookups");check(!source.lookups.containsKey("org.installed.app"),"Already enumerated packages need no lookup");check(result.packageFailures==2,"Malformed entry and not-installed lookup do not erase other apps");
 source=new Fake();source.failAll=true;result=new InstalledPackages<>(source).collect(Arrays.asList("org.tracked.app"));check(result.packages.size()==3&&result.sourceFailures==1,"Launcher and tracked lookups recover when enumeration fails");
 source=new Fake();source.failLauncher=true;result=new InstalledPackages<>(source).collect(Collections.emptyList());check(result.packages.size()==2&&result.sourceFailures==1,"Launcher failure preserves main inventory");
 source=new Fake();source.all=Collections.emptyList();source.failLauncher=true;result=new InstalledPackages<>(source).collect(Arrays.asList("org.tracked.app","org.missing"));check(result.packages.size()==1&&result.packages.containsKey("org.tracked.app"),"Known packages are individually confirmed with Android");
 source=new Fake();source.all=Collections.emptyList();source.failLauncher=true;result=new InstalledPackages<>(source).collect(Arrays.asList("org.external.app"));check(result.packages.containsKey("org.external.app"),"Opening a known catalog package recognizes an external APK even without launcher enumeration or Kivo download history");
 System.out.println("PASS: inventory source fallback, external installs, one bad entry isolation, deduplication and downloaded/uninstalled distinction.");
 }
}
